from __future__ import annotations

import re

_I = re.I
_KIN = r"(?:พ่อ|แม่|ปู่|ย่า|ตา|ยาย|สามี|ภรรยา|เมีย|ผัว|แฟน|พี่ชาย|พี่สาว|น้องชาย|น้องสาว|ลูก|ป้า|ลุง|น้า|อา|เพื่อนสนิท)"
_PAIR = r"(?:แฟน|สามี|ภรรยา|เมีย|ผัว|คู่)"
_CRISIS = r"อยากตาย|ไม่อยากอยู่|ฆ่าตัว|จบชีวิต|ทำร้ายตัวเอง|กรีด"


def _rx(p: str) -> re.Pattern:
    return re.compile(p, _I)


def _L(key, th, no, open_, paths, ask, vega, verdict=None, over=()):
    """over = หัวข้อด่วนที่เลนส์นี้รับแทนได้ (เช่น รถชนที่ไม่มีคนเจ็บ ไม่ใช่เรื่องปฐมพยาบาล) — `no` ต้องกันกรณีที่ด่วนจริงไว้"""
    d = {"key": key, "th": _rx(th), "en": None, "no": _rx(no) if no else None, "over": tuple(over),
         "th_d": {"vega": vega, "open": [open_], "paths": list(paths), "ask": ask}}
    if verdict:
        d["verdict"] = (verdict, verdict)
    return d


